// Claude replies with text. Take the content out of it, and stop here if any
// part is missing or far too long, before anything is generated or rendered.
const answer = String($json.text ?? '');
const start = answer.indexOf('{');
const end = answer.lastIndexOf('}');
if (start < 0 || end <= start) {
  throw new Error(`Claude did not reply with the content. It said: ${answer.slice(0, 200)}`);
}
const c = JSON.parse(answer.slice(start, end + 1));

const problems = [];
const str = (path, value, max) => {
  if (typeof value !== 'string' || !value.trim()) problems.push(`${String(path)} is missing`);
  // The design shrinks long words to fit, up to about half again the limit.
  else if (max && value.length > max * 1.5) problems.push(`${String(path)} is ${value.length} characters, the limit is ${String(max)}`);
};
const list = (path, value, count, max) => {
  if (!Array.isArray(value) || value.length !== count) problems.push(`${String(path)} needs ${String(count)} items`);
  else value.forEach((v, i) => str(`${String(path)}[${String(i)}]`, v, max));
};
str('brand', c.brand, 20);
str('product', c.product, 22);
for (const k of ['dark', 'light', 'accent']) {
  if (!/^#[0-9a-fA-F]{6}$/.test(c.colours?.[k] ?? '')) problems.push(`colours.${String(k)} is not a #rrggbb colour`);
}
str('heroPrompt', c.heroPrompt);
str('musicPrompt', c.musicPrompt);
str('clipPrompt', c.clipPrompt);
list('lines', c.lines, 8);
list('hook', c.hook, 2, 15);
str('stat.heading', c.stat?.heading, 15);
str('stat.value', c.stat?.value, 4);
str('stat.label', c.stat?.label, 13);
str('stat.detail', c.stat?.detail, 34);
str('feature.label', c.feature?.label, 15);
str('feature.detail', c.feature?.detail, 30);
str('stepsHeading', c.stepsHeading, 14);
list('steps', c.steps, 3, 28);
str('benefit', c.benefit, 24);
list('chips', c.chips, 3, 16);
str('tagline', c.tagline, 40);
if (problems.length) throw new Error(`Claude's content needs another run: ${problems.join('; ')}`);

c.stat.percent = Number.isFinite(c.stat.percent) ? c.stat.percent : null;
return [{ json: { content: c } }];

// Build the video: turns Claude's content into a Shotstack edit with a fixed
// infographic design. Each scene takes its start and length from its own
// voiceover line (alias://lineN), so the picture always lands on the words.
// This file is the body of the workflow's "Build the video" Code node; the
// test harness at the bottom only runs outside n8n.

function buildEdit(c, heroUrl, musicUrl, clipPrompt) {
  const W = 1080, H = 1920;
  const FONTS = {
    montserrat: ['https://fonts.gstatic.com/s/montserrat/v31/JTUSjIg1_i6t8kCHKm45xW5rygbi49c.ttf', 'JTUSjIg1_i6t8kCHKm45xW5rygbi49c'],
    anton: ['https://fonts.gstatic.com/s/anton/v27/1Ptgg87LROyAm0K08i4gS7lu.ttf', '1Ptgg87LROyAm0K08i4gS7lu'],
    playfair: ['https://fonts.gstatic.com/s/playfairdisplay/v40/nuFiD-vYSZviVYUb_rj3ij__anPXPTvSgWE_-xU.ttf', 'nuFiD-vYSZviVYUb_rj3ij__anPXPTvSgWE_-xU'],
  };
  const D = c.colours.dark, L = c.colours.light, A = c.colours.accent;
  const tracks = [];
  const layer = (...clips) => tracks.push({ clips });
  // Scenes are numbered lines; 'outro' is the silent beat after the last line.
  // Only the music, which starts at zero, uses length 'end'. On a clip that starts
  // at an alias, Shotstack sizes 'end' as if it started at zero: the end card doubled.
  const line = (n) => `alias://${typeof n === 'number' ? 'line' + n : n}`;
  const at = (cx, cy) => ({ x: +((cx - W / 2) / W).toFixed(4), y: +((H / 2 - cy) / H).toFixed(4) });
  // Longer words get a smaller size to start with; text() then makes sure they fit.
  const fit = (s, base, max) => Math.round(base * Math.min(1, max / Math.max(String(s).length, 1)));
  // Average glyph widths in em (capitals, small letters, digits, space), measured from the
  // font files at the weights used here. Real words come within about 10% of the estimate.
  const EM = { montserrat: [0.743, 0.615, 0.62, 0.291], anton: [0.474, 0.455, 0.478, 0.234], playfair: [0.681, 0.527, 0.516, 0.233] };

  function text(words, font, size, color, cx, cy, w, h, scene, o = {}) {
    // Shrink the words until they fit their box: no word wider than the box, and every
    // wrapped line inside its height. ponytail: estimated widths plus 10%, not real text layout.
    const spacing = o.spacing ?? 0, em = EM[font], parts = String(words).split(' ');
    const wide = (t, px) => 1.1 * [...t].reduce((n, ch) =>
      n + px * (ch === '%' ? 1.06 : em[/[A-Z]/.test(ch) ? 0 : /\d/.test(ch) ? 2 : ch === ' ' ? 3 : 1]) + spacing, 0);
    const lines = (px) => parts.reduce(([n, cur], t) => {
      const next = cur ? cur + wide(' ', px) + wide(t, px) : wide(t, px);
      return next > w && cur ? [n + 1, wide(t, px)] : [n, next];
    }, [1, 0])[0];
    const fits = (px) => parts.every((t) => wide(t, px) <= w) && lines(px) * px * 1.2 <= h;
    while (size > 12 && !fits(size)) size--;
    const asset = {
      type: 'rich-text', text: String(words),
      font: { family: FONTS[font][1], size, weight: o.weight ?? '800', color },
      style: { letterSpacing: o.spacing ?? 0, lineHeight: 1.05 },
      align: { horizontal: o.align ?? 'center', vertical: 'middle' },
    };
    if (o.anim !== null) asset.animation = { preset: o.anim ?? 'ascend', direction: 'up', duration: o.duration ?? 0.6 };
    return { asset, start: o.start ?? line(scene), length: o.length ?? line(scene), width: w, height: h, position: 'center', offset: at(cx, cy) };
  }

  function html5(scene, body, css, js, o = {}) {
    const base = 'html,body{margin:0;padding:0;width:1080px;height:1920px;background:transparent;overflow:hidden}*{box-sizing:border-box}.abs{position:absolute;left:0;top:0}';
    return { asset: { type: 'html5', html: body, css: base + css, js }, start: o.start ?? line(scene), length: o.length ?? line(scene) };
  }
  const svg = (inner) => `<svg class="abs" width="1080" height="1920">${String(inner)}</svg>`;

  function hero(scene, o = {}) {
    const clip = { asset: { type: 'image', src: heroUrl }, start: o.start ?? line(scene), length: o.length ?? line(scene), fit: 'crop' };
    if (o.scale) clip.scale = o.scale;
    if (o.x) clip.offset = { x: o.x, y: 0 };
    return clip;
  }

  // ---------------------------------------------------------------- wipes (top layers)
  layer(html5(3, `<div id="p" class="abs" style="width:1080px;height:1920px;background:${String(D)}"></div>`, '',
    "gsap.timeline().to('#p',{y:-1920,duration:0.4,ease:'power3.in'},0);", { length: 0.45 }));
  layer(html5(6, `<div id="p" class="abs" style="width:1080px;height:1920px;background:${String(D)}"></div>`, '',
    "gsap.timeline().to('#p',{x:-1080,duration:0.35,ease:'power3.out'},0);", { length: 0.4 }));
  layer(html5(8, `<div id="p" class="abs" style="width:1080px;height:1920px;background:${String(A)}"></div>`, '',
    "gsap.timeline().to('#p',{x:1080,duration:0.4,ease:'power3.out'},0);", { length: 0.45 }));

  // ---------------------------------------------------------------- words
  const hookA = c.hook[0], hookB = c.hook[1];
  layer(text(hookA, 'anton', fit(hookA, 230, 9), L, 540, 720, 1000, 300, 1, { weight: '400' }));
  layer(text(hookA, 'anton', fit(hookA, 230, 9), L, 540, 720, 1000, 300, 2, { weight: '400', anim: null }));
  layer(text(hookB, 'anton', fit(hookB, 128, 15), A, 540, 930, 1000, 170, 2, { weight: '400' }));

  layer(text(c.brand.toUpperCase(), 'montserrat', fit(c.brand, 44, 20), D, 540, 225, 1000, 80, 3, { spacing: 16 }));
  layer(text(c.product, 'playfair', fit(c.product, 86, 21), D, 540, 335, 1040, 130, 3, { weight: '700' }));

  const s = c.stat, f = c.feature;
  for (const scene of [4, 5]) {
    const still = scene === 5 ? { anim: null } : {};
    layer(text(s.heading.toUpperCase(), 'montserrat', fit(s.heading, 40, 15), A, 845, 330, 440, 70, scene, { spacing: 8, ...still }));
    // 160 wide keeps the number well inside the ring, which is 218 across on the inside.
    layer(text(s.value, 'anton', fit(s.value, 106, 4), D, 840, 560, 160, 140, scene, { weight: '400', ...still }));
    layer(text(s.label.toUpperCase(), 'montserrat', fit(s.label, 54, 13), D, 845, 752, 440, 70, scene, still));
    layer(text(s.detail, 'montserrat', 36, D, 845, 845, 420, 100, scene, { weight: '500', ...still }));
  }
  layer(text(f.label.toUpperCase(), 'montserrat', fit(f.label, 40, 15), D, 845, 1255, 440, 70, 5));
  layer(text(f.detail, 'montserrat', 36, D, 845, 1335, 440, 100, 5, { weight: '500' }));

  layer(text(c.stepsHeading.toUpperCase(), 'anton', fit(c.stepsHeading, 80, 16), L, 540, 1160, 1000, 110, 6, { weight: '400', spacing: 4 }));
  c.steps.forEach((step, i) => {
    const cy = 1300 + i * 140;
    layer(text(String(i + 1), 'anton', 58, D, 150, cy, 92, 92, 6, { weight: '400', anim: 'fadeIn', duration: 0.4 + i * 0.25 }));
    layer(text(step, 'montserrat', fit(step, 46, 28), L, 630, cy, 820, 100, 6, { weight: '700', align: 'left', duration: 0.5 + i * 0.25 }));
  });

  layer(text(c.benefit.toUpperCase(), 'anton', fit(c.benefit, 124, 20), L, 540, 1170, 980, 320, 7, { weight: '400' }));

  layer(text(c.tagline, 'playfair', fit(c.tagline, 86, 40), D, 540, 300, 960, 260, 8, { weight: '700' }),
        text(c.tagline, 'playfair', fit(c.tagline, 86, 40), D, 540, 300, 960, 260, 'outro', { weight: '700', anim: null }));
  // Chip widths follow their words; the row is centred and shrinks to fit.
  let chipSize = 30, chipW = c.chips.map((t) => Math.round(t.length * 19.8 + 60));
  const rowWidth = () => chipW.reduce((a, b) => a + b, 0) + 30 * (chipW.length - 1);
  if (rowWidth() > 1000) { chipSize = 26; chipW = c.chips.map((t) => Math.round(t.length * 17.2 + 50)); }
  let x = (W - rowWidth()) / 2;
  const chips = c.chips.map((t, i) => { const chip = { t, x, w: chipW[i] }; x += chipW[i] + 30; return chip; });
  chips.forEach((chip) => layer(
    text(chip.t.toUpperCase(), 'montserrat', chipSize, D, chip.x + chip.w / 2, 1612, chip.w, 72, 8, { spacing: 1, anim: 'fadeIn', duration: 0.5 }),
    text(chip.t.toUpperCase(), 'montserrat', chipSize, D, chip.x + chip.w / 2, 1612, chip.w, 72, 'outro', { spacing: 1, anim: null })));
  const pillWords = `${c.brand}  ·  ${c.product}`.toUpperCase();
  const pillSize = fit(pillWords, 30, 38);
  const pillW = Math.min(1000, Math.round(pillWords.length * pillSize * 0.72 + 90));
  layer(text(pillWords, 'montserrat', pillSize, L, 540, 1748, pillW, 96, 8, { spacing: 2, anim: 'fadeIn', duration: 0.6 }),
        text(pillWords, 'montserrat', pillSize, L, 540, 1748, pillW, 96, 'outro', { spacing: 2, anim: null }));

  // ---------------------------------------------------------------- graphics
  const dots = [380, 540, 700].map((dx, i) =>
    `<g transform="translate(${String(dx)},1450)"><circle id="d${String(i)}" r="34" fill="${String(A)}"/></g>` +
    `<circle id="r${String(i)}" cx="${String(dx)}" cy="1450" r="34" fill="none" stroke="${String(A)}" stroke-width="6" opacity="0"/>`).join('');
  layer(html5(1, `<div class="abs" style="width:1080px;height:1920px;background:${String(D)}">${svg(dots)}</div>`, '',
    "const t=gsap.timeline();[0,1,2].forEach(i=>{const s=0.05+i*0.2;" +
    "t.fromTo('#d'+i,{y:-1650},{y:0,duration:0.42,ease:'power2.in'},s).to('#d'+i,{opacity:0,duration:0.05},s+0.42)" +
    ".fromTo('#r'+i,{scale:0.3,opacity:1,transformOrigin:'50% 50%'},{scale:3.2,opacity:0,duration:0.7,ease:'power2.out'},s+0.42);});"));
  layer(html5(2, `<div class="abs" style="width:1080px;height:1920px;background:${String(D)}"></div>`, '', ''));

  const corners = [[300, 420, 1, 1], [780, 420, -1, 1], [300, 1540, 1, -1], [780, 1540, -1, -1]];
  layer(html5(3, svg(corners.map(([cx, cy, sx, sy]) =>
    `<path class="br" d="M${String(cx)},${cy + 80 * sy} L${String(cx)},${String(cy)} L${cx + 80 * sx},${String(cy)}" fill="none" stroke="${String(A)}" stroke-width="7" stroke-linecap="round"/>`).join('')), '',
    "gsap.set('.br',{strokeDasharray:160,strokeDashoffset:160});gsap.timeline().to('.br',{strokeDashoffset:0,duration:0.55,ease:'power2.out',stagger:0.08},0.25);"));

  const RING = 2 * Math.PI * 120;
  const pct = Number.isFinite(s.percent) ? Math.max(0, Math.min(100, s.percent)) : 100;
  const ringEnd = (RING * (1 - pct / 100)).toFixed(1);
  const ICONS = {
    drop: 'M0,-62 C24,-28 42,-4 42,20 A42,42 0 1 1 -42,20 C-42,-4 -24,-28 0,-62Z',
    leaf: 'M-40,40 C-50,-20 0,-60 50,-50 C55,0 20,50 -40,40Z',
    sun: 'M0,-45 A45,45 0 1 1 0,45 A45,45 0 1 1 0,-45Z',
    heart: 'M0,40 C-60,0 -50,-50 0,-20 C50,-50 60,0 0,40Z',
    star: 'M0,-55 L16,-17 L57,-17 L24,7 L36,47 L0,23 L-36,47 L-24,7 L-57,-17 L-16,-17Z',
    shield: 'M0,-55 L45,-38 L45,5 C45,32 22,50 0,58 C-22,50 -45,32 -45,5 L-45,-38Z',
  };
  const icon = ICONS[f.icon] || ICONS.star;
  const statSvg = (live) =>
    `<circle id="dot1" cx="568" cy="1060" r="12" fill="${String(A)}"/>` +
    `<polyline id="l1" points="568,1060 605,1060 605,560 716,560" fill="none" stroke="${String(D)}" stroke-width="4"/>` +
    `<circle id="track" cx="840" cy="560" r="120" fill="none" stroke="${String(D)}" stroke-opacity="0.15" stroke-width="22"/>` +
    `<circle id="ring" cx="840" cy="560" r="120" fill="none" stroke="${String(A)}" stroke-width="22" stroke-linecap="round" transform="rotate(-90 840 560)" ` +
    `stroke-dasharray="${RING.toFixed(1)}" stroke-dashoffset="${live ? RING.toFixed(1) : ringEnd}"/>`;
  layer(html5(4, svg(statSvg(true)), '',
    "gsap.set('#l1',{strokeDasharray:1000,strokeDashoffset:1000});gsap.set(['#dot1','#track'],{scale:0,transformOrigin:'50% 50%'});" +
    "gsap.timeline().to('#dot1',{scale:1,duration:0.3,ease:'back.out(2)'},0.15).to('#l1',{strokeDashoffset:0,duration:0.6,ease:'power2.inOut'},0.25)" +
    `.to('#track',{scale:1,duration:0.4,ease:'power3.out'},0.5).to('#ring',{strokeDashoffset:${String(ringEnd)},duration:1.1,ease:'power2.out'},0.75);`));
  layer(html5(5, svg(statSvg(false) +
    `<circle id="dot2" cx="568" cy="1430" r="12" fill="${String(A)}"/>` +
    `<polyline id="l2" points="568,1430 625,1430 625,1100 778,1100" fill="none" stroke="${String(D)}" stroke-width="4"/>` +
    `<clipPath id="ic"><path d="${String(icon)}" transform="translate(840,1100) scale(1.3)"/></clipPath>` +
    `<g clip-path="url(#ic)"><rect id="fill" x="760" y="1000" width="160" height="200" fill="${String(A)}"/></g>` +
    `<g id="iconG"><path d="${String(icon)}" transform="translate(840,1100) scale(1.3)" fill="none" stroke="${String(D)}" stroke-width="5"/></g>`), '',
    "gsap.set('#l2',{strokeDasharray:1000,strokeDashoffset:1000});gsap.set('#dot2',{scale:0,transformOrigin:'50% 50%'});" +
    "gsap.set('#iconG',{scale:0,svgOrigin:'840 1100'});gsap.set('#fill',{y:200});" +
    "gsap.timeline().to('#dot2',{scale:1,duration:0.3,ease:'back.out(2)'},0.1).to('#l2',{strokeDashoffset:0,duration:0.5,ease:'power2.inOut'},0.2)" +
    ".to('#iconG',{scale:1,duration:0.4,ease:'back.out(1.6)'},0.45).to('#fill',{y:0,duration:1.1,ease:'power2.out'},0.7);"));

  layer(html5(6, svg(
    `<rect x="0" y="1060" width="1080" height="860" fill="${String(D)}"/>` +
    `<line id="conn" x1="150" y1="1300" x2="150" y2="1580" stroke="${String(A)}" stroke-width="5" stroke-opacity="0.6"/>` +
    [0, 1, 2].map((i) => `<circle class="c" id="c${String(i)}" cx="150" cy="${1300 + i * 140}" r="46" fill="${String(A)}"/>`).join('')), '',
    "gsap.set('.c',{scale:0,transformOrigin:'50% 50%'});gsap.set('#conn',{strokeDasharray:280,strokeDashoffset:280});" +
    "gsap.timeline().to('.c',{scale:1,duration:0.35,ease:'back.out(2)',stagger:0.25},0.15).to('#conn',{strokeDashoffset:0,duration:0.6,ease:'none'},0.3);"));

  layer(html5(7, `<div class="abs" style="width:1080px;height:1920px;background:${String(D)}">${svg(
    `<circle id="halo" cx="540" cy="760" r="170" fill="none" stroke="${String(A)}" stroke-width="6" opacity="0.5"/>` +
    `<circle id="disc" cx="540" cy="760" r="150" fill="${String(A)}"/>` +
    `<path id="tick" d="M470,765 L522,815 L615,705" fill="none" stroke="${String(D)}" stroke-width="26" stroke-linecap="round" stroke-linejoin="round"/>`)}</div>`, '',
    "gsap.set(['#disc','#halo'],{scale:0,transformOrigin:'50% 50%'});gsap.set('#tick',{strokeDasharray:300,strokeDashoffset:300});" +
    "gsap.timeline().to('#disc',{scale:1,duration:0.45,ease:'back.out(1.8)'},0.05).to('#tick',{strokeDashoffset:0,duration:0.4,ease:'power2.out'},0.35)" +
    ".fromTo('#halo',{scale:0.9,opacity:0.6},{scale:1.5,opacity:0,duration:1.2,ease:'power2.out'},0.4);"));

  const endSvg = (still) => svg(
    chips.map((chip) => `<rect class="chip" x="${chip.x.toFixed(0)}" y="1576" width="${chip.w}" height="72" rx="36" fill="#FFFFFF" fill-opacity="0.9"/>`).join('') +
    `<clipPath id="pc"><rect x="${540 - pillW / 2}" y="1700" width="${String(pillW)}" height="96" rx="48"/></clipPath>` +
    `<g id="pill"><rect x="${540 - pillW / 2}" y="1700" width="${String(pillW)}" height="96" rx="48" fill="${String(D)}"/>` +
    (still ? '' : `<g clip-path="url(#pc)"><rect id="shine" x="-200" y="1690" width="120" height="120" fill="#FFFFFF" fill-opacity="0.25" transform="skewX(-20)"/></g>`) + '</g>');
  layer(html5(8, endSvg(false), '',
    "gsap.set('.chip',{scale:0.6,opacity:0,transformOrigin:'50% 50%'});gsap.set('#pill',{scale:0.8,opacity:0,svgOrigin:'540 1748'});" +
    "gsap.timeline().to('.chip',{scale:1,opacity:1,duration:0.35,ease:'back.out(1.8)',stagger:0.15},0.1)" +
    ".to('#pill',{scale:1,opacity:1,duration:0.4,ease:'back.out(1.6)'},0.45).to('#shine',{x:1500,duration:0.9,ease:'power2.inOut'},1.1);"),
    html5('outro', endSvg(true), '', ''));

  // ---------------------------------------------------------------- pictures
  if (clipPrompt) {
    layer({ asset: { type: 'video', prompt: clipPrompt, model: 'seedance-2.0-image-to-video',
                     options: { startSrc: heroUrl, resolution: '720p', aspectRatio: '9:16' } },
            start: line(6), length: 5, width: 1080, height: 1060, fit: 'crop', position: 'center', offset: { x: 0, y: 0.224 } });
  } else {
    layer({ asset: { type: 'image', src: heroUrl }, start: line(6), length: line(6), width: 1080, height: 1060, fit: 'crop',
            position: 'center', offset: { x: 0, y: 0.224 }, scale: [{ from: 1.15, to: 1.25, start: 0, length: 5 }] });
  }
  layer(
    hero(3, { scale: [{ from: 1.08, to: 1.0, start: 0, length: 3.5, easing: 'easeOutCubic' }] }),
    hero(4, { scale: [{ from: 1.0, to: 1.4, start: 0, length: 0.8, easing: 'easeInOutCubic' }, { from: 1.4, to: 1.44, start: 0.8, length: 6 }],
              x: [{ from: 0, to: -0.2, start: 0, length: 0.8, easing: 'easeInOutCubic' }] }),
    hero(5, { scale: [{ from: 1.44, to: 1.48, start: 0, length: 6 }], x: -0.2 }),
    hero(8, { scale: [{ from: 1.0, to: 1.05, start: 0, length: 4, easing: 'easeOutSine' }] }),
    hero('outro', { scale: [{ from: 1.05, to: 1.06, start: 0, length: 2 }] }),
  );

  // ---------------------------------------------------------------- sound
  const voice = { voice: c.voice || 'Rachel', stability: 0.45, style: 0.35 };
  layer(
    ...c.lines.map((words, i) => ({ alias: `line${i + 1}`, asset: { type: 'audio', prompt: words, model: 'elevenlabs-multilingual-v2', options: voice },
                                     start: i === 0 ? 0.15 : 'auto', length: 'auto' })),
    // A beat of silence after the last line, so the end card can breathe.
    { alias: 'outro', asset: { type: 'html5', html: '<div></div>' }, start: 'auto', length: 1.3 },
  );
  layer({ asset: { type: 'audio', src: musicUrl, volume: 0.22, effect: 'fadeOut' }, start: 0, length: 'end' });

  return {
    timeline: { background: L, fonts: Object.values(FONTS).map(([src]) => ({ src })), tracks },
    output: { format: 'mp4', size: { width: W, height: H }, fps: 30 },
  };
}

const c = $('Check the content').first().json.content;
const heroUrl = $('Make the hero photo').first().json.url;
const musicUrl = $json.url;
const shot = /^\s*y/i.test(String($('This row').first().json['Animated AI shot'] ?? ''));
// The saved video is named after the row number, the brand and the product.
const fileName = `${$runIndex + 1} ${c.brand} ${c.product}`.replace(/[\\/:*?"<>|]/g, '') + '.mp4';
return [{ json: { edit: buildEdit(c, heroUrl, musicUrl, shot ? c.clipPrompt : null), fileName } }];

// One line of the results file for each row: the row as it was, plus the saved
// video, or the first step that failed and why. A failed row never stops the others.
const row = $('This row').first().json;
for (const step of ["Claude writes the content", "Check the content", "Make the hero photo", "Make the music", "Build the video", "Make the video", "Wait for the video", "Download the video", "Save the video"]) {
  const out = $(step).first();
  const error = out?.error ?? out?.json?.error;
  if (!out || error) {
    const why = typeof error === 'string' ? error : error?.message ?? 'open this run in n8n to see why';
    return [{ json: { ...row, Video: '', Result: `Failed at "${String(step)}": ${String(why)}` } }];
  }
}
return [{ json: { ...row, Video: $('Build the video').first().json.fileName, Result: 'Done' } }];
